import React, { useState } from "react";
import { Link } from "react-router-dom";
import wordCloudImage from "./test1.jpg";

export default function Summary() {
  const [hovered, setHovered] = useState(false);

  return (
    <div
      style={{
        position: "relative",
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        padding: "2rem",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
        background: "linear-gradient(135deg, #11998e 0%, #ffc3a0 100%)",
        color: "#333",
        textAlign: "center",
      }}
    >
      {/* Summary Section */}
      <div>
        <h2 style={{ fontSize: "2.5rem", fontWeight: "700", marginBottom: "1rem" }}>
          Summary of Comments
        </h2>
        <p style={{ fontSize: "1.2rem", opacity: 0.85 }}>👉 Your summary output will appear here...</p>
        <Link to="/" style={{ marginTop: "2rem", textDecoration: "none", display: "inline-block" }}>
          <button
            style={{
              background: "linear-gradient(135deg, #6a11cb 0%, #2575fc 100%)",
              border: "none",
              borderRadius: "30px",
              padding: "12px 28px",
              fontSize: "1.1rem",
              fontWeight: "600",
              color: "#fff",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(37, 117, 252, 0.6)",
              transition: "all 0.3s ease",
              minWidth: "180px",
            }}
            onMouseEnter={(e) => {
              e.target.style.background = "linear-gradient(135deg, #2575fc 0%, #6a11cb 100%)";
              e.target.style.boxShadow = "0 6px 20px rgba(106, 17, 203, 0.75)";
            }}
            onMouseLeave={(e) => {
              e.target.style.background = "linear-gradient(135deg, #6a11cb 0%, #2575fc 100%)";
              e.target.style.boxShadow = "0 4px 15px rgba(37, 117, 252, 0.6)";
            }}
          >
            Back
          </button>
        </Link>
      </div>

      {/* Vertical Tab */}
      <div
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        style={{
          position: "fixed",
          right: 0,
          top: 0,
          height: "100vh",
          width: "40px",
          backgroundColor: "#6a11cb",
          color: "#fff",
          fontWeight: "700",
          fontSize: "1rem",
          letterSpacing: "0.1em",
          cursor: "pointer",
          userSelect: "none",
          writingMode: "vertical-rl",
          textOrientation: "mixed",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 1000,
        }}
      >
        Word Cloud
      </div>

      {/* Enlarged Word Cloud Image */}
      {hovered && (
        <div
          style={{
            position: "fixed",
            right: "40px",
            top: "50%",
            transform: "translateY(-50%)",
            width: "300px",
            borderRadius: "15px",
            boxShadow: "0 4px 20px rgba(106, 17, 203, 0.75)",
            backgroundColor: "#fff",
            padding: "0.5rem",
            zIndex: 1100,
            transition: "all 0.3s ease",
          }}
        >
          <img
            src={wordCloudImage}
            alt="wordcloud"
            style={{ width: "100%", borderRadius: "12px" }}
          />
        </div>
      )}
    </div>
  );
}
